 g+='<rect x="'+(S.x+S.w/2-34)+'" y="19" width="68" height="14" fill="#FFFDF7"/><text x="'+(S.x+S.w/2)+'" y="30" font-size="10" text-anchor="middle" fill="#0E3A8A">'+S.w+' m</text>';
