 var sb=S.y+S.h+34;g+='<g transform="translate('+S.x+' '+sb+')"><rect width="50" height="7" fill="#071A44"/><rect x="50" width="50" height="7" fill="#FFFDF7" stroke="#071A44"/><rect x="100" width="50" height="7" fill="#071A44"/><text y="22" font-size="9" fill="#071A44">0</text><text x="48" y="22" font-size="9" fill="#071A44">50</text><text x="96" y="22" font-size="9" fill="#071A44">100</text><text x="146" y="22" font-size="9" fill="#071A44">150 m</text></g>';
 g+='<text x="'+(S.x+S.w)+'" y="'+(sb+19)+'" font-size="10" text-anchor="end" fill="#5A6278">SITE PLAN NO. '+('0'+seed).slice(-2)+' · '+plots.length+' PLOTS</text>';
