var TIER=[['Very important','t1'],['Important','t2'],['Moderate','t3'],['Least important','t4']];
var tcls=function(t){for(var i=0;i<TIER.length;i++)if(TIER[i][0]===t)return TIER[i][1];return 't4'};
var SECDEF={maths:{label:'Mathematics',list:D.maths,total:25,prefix:'M',nm:function(c){return c.name}},apt:{label:'Aptitude',list:D.apt,total:50,prefix:'A',nm:function(c){return c.name}},plan:{label:'Planning',list:D.plan,total:25,prefix:'P',nm:function(c){return c.name}}};
var curSec='maths',curTier='all',curTile=null;
function squarify(items,x,y,w,h){var rects=[],total=items.reduce(function(s,i){return s+i.v},0),sc=w*h/total,list=items.map(function(i){return {it:i,a:i.v*sc}});
 function worst(row,sum,side){var mx=0,mn=Infinity;row.forEach(function(r){mx=Math.max(mx,r.a);mn=Math.min(mn,r.a)});return Math.max(side*side*mx/(sum*sum),sum*sum/(side*side*mn))}
 (function lay(list,x,y,w,h){if(!list.length)return;var side=Math.min(w,h),row=[],rowA=0,best=Infinity,i=0;
  while(i<list.length){var cand=row.concat([list[i]]),s=rowA+list[i].a,ws=worst(cand,s,side);if(row.length&&ws>best)break;row=cand;rowA=s;best=ws;i++}
  var thick=rowA/side,off=0;
  if(w>=h){row.forEach(function(r){var hh=r.a/thick;rects.push({it:r.it,x:x,y:y+off,w:thick,h:hh});off+=hh});lay(list.slice(i),x+thick,y,w-thick,h)}
  else{row.forEach(function(r){var ww=r.a/thick;rects.push({it:r.it,x:x+off,y:y,w:ww,h:thick});off+=ww});lay(list.slice(i),x,y+thick,w,h-thick)}})(list,x,y,w,h);
 return rects}
