 rects.forEach(function(r){var c=r.it.c,a=r.w*r.h/(W*H),wpx=r.w/W*cw,hpx=r.h/H*ch,sz=(wpx<(mobile?96:72)||hpx<(mobile?70:54))?'x':a>.13?'l':a>.055?'m':'s',key=def.prefix+(r.it.i+1);
  html+='<div class="tl" style="left:'+(r.x/W*100)+'%;top:'+(r.y/H*100)+'%;width:'+(r.w/W*100)+'%;height:'+(r.h/H*100)+'%"><button type="button" class="tile '+tcls(c.tier)+'" data-sz="'+sz+'" data-i="'+r.it.i+'" data-tier="'+esc(c.tier)+'" aria-pressed="false" aria-label="'+esc(c.name)+', '+esc(c.tier)+', '+fmt(c.v)+' of '+def.total+' questions per paper" title="'+esc(c.name)+'"><span class="tk">'+(c.key||key)+'</span><span class="tn">'+esc(c.name)+'</span><span class="tv">'+fmt(c.v)+'<small> / '+def.total+'</small></span></button></div>'});
 host.innerHTML=html;
