var L='ABCD',Q=D.diag.map(function(d){var o=d.wrong.slice();o.splice(d.pos,0,d.correct);return {sec:d.sec,q:d.q,opts:o,ans:d.pos,why:d.why}});
var saved=store.get('check'),ans=(saved&&saved.ans&&saved.ans.length===Q.length)?saved.ans:Q.map(function(){return null}),qi=0,done=!!(saved&&saved.done),cur=null;
