 box.innerHTML=progress()+'<div class="fadein"><span class="qsec">'+q.sec+' · Question '+(qi+1)+' of '+Q.length+'</span><div class="qtext">'+esc(q.q)+'</div><div class="opts">'+q.opts.map(function(o,j){return '<button type="button" class="opt" data-j="'+j+'" aria-pressed="'+(ans[qi]===j)+'"><i>'+L[j]+'</i><span>'+esc(o)+'</span></button>'}).join('')+'</div></div>'+
 '<div class="qnav"><button class="btn-ghost btn-sm" id="qprev" type="button"'+(qi===0?' disabled style="opacity:.4;cursor:default"':'')+'>← Back</button><span class="kv">'+n+' of '+Q.length+' answered</span><div class="row"><button class="btn-ghost btn-sm" id="qskip" type="button">Skip</button>'+(last||n===Q.length?'<button class="btn-primary btn-sm" id="qfin" type="button">See my result <span class="ar">→</span></button>':'<button class="btn-primary btn-sm" id="qnext" type="button">Next <span class="ar">→</span></button>')+'</div></div>';
 bindProg();
 $$('#qcard .opt').forEach(function(b){b.addEventListener('click',function(){ans[qi]=+b.dataset.j;store.set('check',{ans:ans,done:false});renderQ()})});
