 $('#gsrc').textContent=useMock?'Using your mock test numbers. Replace the example values with your own.':(cur?'Using your starter check result.':'Showing example numbers (a student with 10 of 20 correct) until you finish the starter check.');
 var ms=EX[ex]-new Date(),weeks=Math.max(0,Math.floor(ms/6048e5)),days=Math.max(0,Math.floor((ms%6048e5)/864e5)),perw=weeks>0?gap/weeks:gap;
 var cls=gap===0?'No gap':gap<=50?'Small gap':gap<=120?'Medium gap':'Large gap';
